import json
import re
import difflib

response_text = arg0
source_text = arg1

FR_TO_EN = {
    "epee": "sword",
    "bouclier": "shield",
    "torche": "torch",
    "cape": "cloak",
}

for fr, en in FR_TO_EN.items():
    response_text = re.sub(fr, en, response_text, flags=re.IGNORECASE)

match = re.search(r"\{.*\}", response_text, re.DOTALL)
warnings = []

def normalize(name):
    n = name.lower().strip()
    for prefix in ["the ", "a ", "an "]:
        if n.startswith(prefix):
            n = n[len(prefix):]
    return n

def clean_list(lst):
    return [x for x in lst if isinstance(x, str) and x.strip()]

def find_position_ratio(quote, source):
    if not quote or not source:
        return None
    # Recherche approximative : on cherche le meilleur point d'ancrage
    # d'un extrait du début de la citation dans le texte source.
    anchor = quote.strip()[:40]
    idx = source.find(anchor)
    if idx == -1:
        # Recherche floue si la correspondance exacte échoue
        matcher = difflib.SequenceMatcher(None, source, quote)
        block = matcher.find_longest_match(0, len(source), 0, len(quote))
        if block.size < 15:
            return None
        idx = block.a
    return idx / max(len(source), 1)

if not match:
    data = {"error": "no_json_found", "raw": response_text}
    warnings.append("no_json_found")
else:
    try:
        data = json.loads(match.group(0))

        if "characters" in data and isinstance(data["characters"], list):
            seen = set()
            deduped = []
            for c in clean_list(data["characters"]):
                key = normalize(c)
                if key not in seen:
                    seen.add(key)
                    deduped.append(c)
            data["characters"] = deduped

        if "objects" in data and isinstance(data["objects"], list):
            data["objects"] = clean_list(data["objects"])
        if "creatures" in data and isinstance(data["creatures"], list):
            data["creatures"] = clean_list(data["creatures"])

        if isinstance(data.get("objects"), list) and len(data["objects"]) > 4:
            warnings.append(f"too_many_objects_{len(data['objects'])}")

        if not data.get("characters"):
            warnings.append("no_characters")

        for field in ["scene", "environment", "action", "composition"]:
            val = data.get(field, "")
            if not isinstance(val, str) or not val.strip():
                warnings.append(f"empty_field_{field}")

        # Détection mécanique : la citation est-elle trop tôt dans le texte ?
        quote = data.get("last_action_quote", "")
        ratio = find_position_ratio(quote, source_text)
        if ratio is not None and ratio < 0.6:
            warnings.append(f"last_action_quote_too_early_ratio_{ratio:.2f}")

        check_data = {k: v for k, v in data.items() if k != "last_action_quote"}
        full_text = json.dumps(check_data, ensure_ascii=False)
        if re.search(r"[a-zA-Z]*[\xc0-\xff]", full_text):
            warnings.append("residual_non_english_characters")

    except json.JSONDecodeError as e:
        data = {"error": "invalid_json", "detail": str(e), "raw": response_text}
        warnings.append("invalid_json")

data["_warnings"] = warnings
result = json.dumps(data, ensure_ascii=False, indent=2)

import json
from json_repair import repair_json

data = json.loads(repair_json(arg0))

STYLE_GLOBAL = arg1
UNIVERS_GLOBAL = arg2
CONTEXTE_LOCAL = arg3


def to_text(value):
    """Convertit n'importe quelle valeur (str, dict, list, autre) en une
    chaîne de texte lisible, quelle que soit la forme envoyée par le LLM."""
    if value is None:
        return ""
    if isinstance(value, str):
        return value
    if isinstance(value, dict):
        parts = [to_text(v) for v in value.values()]
        return ", ".join(p for p in parts if p)
    if isinstance(value, list):
        parts = [to_text(v) for v in value]
        return ", ".join(p for p in parts if p)
    return str(value)


def to_str_list(value):
    """Convertit n'importe quelle valeur en liste de chaînes de texte."""
    if value is None:
        return []
    if isinstance(value, list):
        return [to_text(v) for v in value if to_text(v)]
    if isinstance(value, dict):
        return [to_text(v) for v in value.values() if to_text(v)]
    if isinstance(value, str) and value.strip():
        return [value]
    return []


characters = ", ".join(to_str_list(data.get("characters"))) or "no characters"
creatures = ", ".join(to_str_list(data.get("creatures")))
objects = ", ".join(to_str_list(data.get("objects")))

scene_line = to_text(data.get("scene"))
environment = to_text(data.get("environment"))
lighting = to_text(data.get("lighting"))
composition = to_text(data.get("composition"))

details = []
if environment:
    details.append(f"Environment: {environment}.")
if creatures:
    details.append(f"Creatures present: {creatures}.")
if objects:
    details.append(f"Visible objects: {objects}.")
if lighting:
    details.append(f"Lighting: {lighting}.")
if composition:
    details.append(f"Composition: {composition}.")

scene_block = scene_line + " " + " ".join(details)

result = f"{STYLE_GLOBAL}\n\n{UNIVERS_GLOBAL}\n\n{CONTEXTE_LOCAL}\n\n{scene_block}"
